import sys
from fractions import Fraction

data = sys.stdin.read().split()
n, W = int(data[0]), int(data[1])
B = [(int(data[2 + 2 * i]), int(data[3 + 2 * i])) for i in range(n)]
if sum(w for w, _ in B) < W:
    print(-1)
else:
    best = None
    for mask in range(1 << n):
        ws = sum(B[i][0] for i in range(n) if mask >> i & 1)
        cs = sum(B[i][1] for i in range(n) if mask >> i & 1)
        if ws >= W:
            cand = [Fraction(cs)]
        else:
            cand = []
            for j in range(n):
                if not mask >> j & 1 and ws + B[j][0] >= W:
                    cand.append(cs + Fraction(B[j][1] * (W - ws), B[j][0]))
        for v in cand:
            if best is None or v < best:
                best = v
    print(best.numerator if best.denominator == 1 else f'{best.numerator}/{best.denominator}')

